mapper.select:
SELECT dp.domestic_product_id, dp.ticker, dp.name, dp.market, dp.type, dp.domestic_stock_ratio, dp.inception_date, dp.sector_name FROM domestic_product dp
dp.type IN
#{t}
AND (dp.name LIKE CONCAT('%', #{keyword}, '%') OR dp.ticker LIKE CONCAT('%', #{keyword}, '%'))
AND EXISTS ( SELECT 1 FROM domestic_product_theme dpt JOIN stock_theme st ON st.stock_theme_id = dpt.stock_theme_id WHERE dpt.domestic_product_id = dp.domestic_product_id AND st.name IN
#{theme}
)
ORDER BY dp.name, dp.ticker
